const express = require('express');
const speakeasy = require('speakeasy');
const crypto = require('crypto');
const { UserRecovery } = require('../models/recovery');

const app = express();
app.use(express.json());

app.post('/api/security/recovery-verify', async (req, res) => {
  // Require verified recovery ticket from out-of-band challenge
  const recoveryTicket = req.headers['x-recovery-ticket'];
  if (!recoveryTicket) {
    return res.status(401).json({ error: 'Recovery challenge ticket required' });
  }

  const session = await UserRecovery.validateRecoveryTicket(recoveryTicket);
  if (!session) {
    return res.status(401).json({ error: 'Invalid or expired recovery session' });
  }

  const { recoveryTotp } = req.body;
  if (!recoveryTotp) {
    return res.status(400).json({ error: 'recoveryTotp required' });
  }

  // Tie lookup strictly to the session's verified user ID
  const user = await UserRecovery.findById(session.userId);
  if (!user || !user.emergencyTotpSecret) {
    return res.status(404).json({ error: 'Recovery profile not found' });
  }

  const delta = speakeasy.totp.verifyDelta({
    secret: user.emergencyTotpSecret,
    encoding: 'base32',
    token: recoveryTotp,
    window: 2
  });

  if (!delta) {
    return res.status(401).json({ error: 'Invalid emergency recovery code' });
  }

  const resetToken = crypto.randomBytes(32).toString('hex');
  await UserRecovery.storeResetToken(user.id, resetToken);

  res.json({ success: true, resetToken });
});

app.listen(6005);
